// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 initialVal, uint256 newVal) internal {
        try c.SetMinSum(initialVal) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.SetMinSum(newVal) {} catch { return; }
        assertTrue(c.MinSum() == initialVal);
    }

    function testFuzz_run(uint256 initialVal, uint256 newVal) public {
        _run(initialVal, newVal);
    }

    receive() external payable {}
}
